// ============================================================================
// ШАГ 1. ВХОДНОЙ БРИФ
// ----------------------------------------------------------------------------
// Узел работает сразу после триггеров (ручная кнопка и webhook) и определяет,
// ОТКУДА брать бриф. По умолчанию — файл brief.json на диске сервера.
// Через webhook можно передать другой путь и точечные правки:
//
//   curl -X POST http://192.168.56.10:5678/webhook/visual-creatives \
//        -H 'Content-Type: application/json' \
//        -d '{"brief_path":"/var/lib/n8n/.n8n-files/visual-creatives/brief.json"}'
//
// Узел не падает, если запущен вручную: у ручного триггера json пустой.
// ============================================================================

const DEFAULT_BRIEF = '/var/lib/n8n/.n8n-files/visual-creatives/brief.json';

const first = $input.first();
const raw = (first && first.json) ? first.json : {};

// webhook в n8n 2.x кладёт тело запроса в поле body, ручной запуск тела не имеет
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const briefPath = (body.brief_path && String(body.brief_path).trim())
  ? String(body.brief_path).trim()
  : DEFAULT_BRIEF;

// Правки поверх брифа: {"fix_threshold": 0} — например, чтобы принудительно
// прогнать ветку исправления при демонстрации.
const overrides = (body.overrides && typeof body.overrides === 'object') ? body.overrides : {};

return [{
  json: {
    brief_path: briefPath,
    overrides: overrides,
    source: body.brief_path ? 'webhook' : 'default',
    started_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

// ============================================================================
// ШАГ 2. РАЗБОР БРИФА И ПЛАН ВАРИАНТОВ
// ----------------------------------------------------------------------------
// Читает текст brief.json (пришёл из узла «Текст брифа»), проверяет, что в брифе
// есть всё обязательное, и собирает из него:
//   • brief_pack — компактный текст брифа для LLM-агента (промт-инженера);
//   • tasks      — список вариантов, которые надо сгенерировать.
//
// Размер генерации выводится из пропорции площадки: генератор даёт картинку
// ровно в нужной пропорции, финальный макет дизайнер собирает уже в размере
// площадки, поэтому «несоответствия по размеру» на этом шаге не возникает.
// ============================================================================

const text = String($input.first().json.data || '').trim();
const entry = $('Входной бриф').first().json;
const overrides = entry.overrides || {};

if (!text) {
  throw new Error('Бриф пуст: узел «Текст брифа» не получил текста из ' + entry.brief_path);
}

let brief;
try {
  brief = JSON.parse(text);
} catch (e) {
  throw new Error('brief.json не разбирается как JSON: ' + e.message);
}

// --- проверка обязательных разделов брифа -----------------------------------
const missing = [];
if (!brief.product || !brief.product.name) missing.push('product');
if (!brief.brand || !brief.brand.name) missing.push('brand');
if (!Array.isArray(brief.segments) || brief.segments.length < 2) {
  missing.push('segments (нужно не менее двух сегментов ЦА)');
}
if (!Array.isArray(brief.placements) || !brief.placements.length) missing.push('placements');
if (!brief.restrictions || !Array.isArray(brief.restrictions.forbidden_elements)) {
  missing.push('restrictions.forbidden_elements');
}
if (!Array.isArray(brief.plan) || !brief.plan.length) missing.push('plan');
if (missing.length) {
  throw new Error('В брифе не хватает обязательных разделов: ' + missing.join(', '));
}

const settings = Object.assign({}, brief.settings || {}, overrides);
const fixThreshold = Number(settings.fix_threshold);
if (!isFinite(fixThreshold)) {
  throw new Error('settings.fix_threshold должен быть числом, получено: ' + settings.fix_threshold);
}

// --- размеры генерации по пропорции площадки --------------------------------
const RATIO_SIZE = {
  '1:1': [1024, 1024],
  '4:5': [1024, 1280],
  '3:4': [768, 1024],
  '4:3': [1024, 768],
  '16:9': [1280, 720]
};

const segById = {};
brief.segments.forEach(function (s) { segById[s.id] = s; });
const plByById = {};
brief.placements.forEach(function (p) { plByById[p.id] = p; });

// Компактный контекст брифа: он поедет вместе с каждым вариантом дальше по
// схеме, чтобы узлы проверки не зависели от данных, прочитанных в начале.
const briefContext = [
  'ПРОДУКТ: ' + brief.product.name + '. ' + brief.product.what,
  'УТП: ' + (brief.product.usp || []).join('; ') + '.',
  'БРЕНД: ' + brief.brand.name + ' — ' + brief.brand.positioning + '.',
  'ПАЛИТРА: ' + Object.keys(brief.brand.palette || {}).map(function (k) {
    return brief.brand.palette[k];
  }).join('; ') + '.',
  'ТОНАЛЬНОСТЬ: ' + brief.brand.tone_of_voice + '.',
  'ЗАПРЕЩЕНО: ' + brief.restrictions.forbidden_elements.join('; ') + '.',
  'ТЕХНИЧЕСКИЕ ОГРАНИЧЕНИЯ: ' + brief.restrictions.technical_restrictions.join('; ') + '.'
].join('\n');

const tasks = brief.plan.map(function (p) {
  const seg = segById[p.segment];
  const pl = plByById[p.placement];
  if (!seg) throw new Error('В плане указан неизвестный сегмент ЦА: ' + p.segment);
  if (!pl) throw new Error('В плане указана неизвестная площадка: ' + p.placement);

  const size = RATIO_SIZE[pl.ratio];
  if (!size) throw new Error('Не знаю размер генерации для пропорции ' + pl.ratio);

  return {
    id: p.id,
    segment_id: seg.id,
    segment_name: seg.name,
    segment_who: seg.who,
    segment_insight: seg.insight,
    segment_message: seg.message,
    // Английские двойники русских полей. Нужны узлу правки: уточнения
    // дописываются прямо в промт, а генератор английский, русского он не
    // понимает — русские фразы в промте для него шум.
    segment_who_en: seg.who_en || seg.who,
    segment_insight_en: seg.insight_en || seg.insight,
    placement_id: pl.id,
    placement_name: pl.name,
    placement_size: pl.size,
    placement_ratio: pl.ratio,
    placement_text_zone: pl.text_zone,
    placement_text_zone_en: pl.text_zone_en || pl.text_zone,
    placement_requirements: pl.requirements,
    style: p.style,
    style_en: p.style_en || p.style,
    composition_focus: p.composition_focus,
    composition_focus_en: p.focus_en || p.composition_focus,
    accent: p.accent,
    seed: p.seed,
    width: size[0],
    height: size[1],
    attempt: 1,
    base_variant: p.base_variant || null,
    changed_parameter: p.changed_parameter || null,
    unchanged_parameters: p.unchanged_parameters || null,
    fallback_prompt: p.fallback_prompt || '',
    // промт подставит LLM-агент; если он не справится — останется запасной
    prompt: p.fallback_prompt || '',
    negative: '',
    rationale: '',
    prompt_source: 'fallback',
    vision_context: briefContext,
    settings: settings
  };
});

// --- текст задания для LLM-агента ------------------------------------------
const pack = [
  'БРИФ НА РЕКЛАМНЫЕ ВИЗУАЛЫ',
  'Кампания: ' + brief.campaign,
  'Продукт: ' + brief.product.name + '. ' + brief.product.what,
  'УТП: ' + (brief.product.usp || []).join('; ') + '.',
  'Призыв к действию: ' + (brief.product.cta || '') + '.',
  '',
  'Бренд: ' + brief.brand.name + ' — ' + brief.brand.positioning + '.',
  'Тональность: ' + brief.brand.tone_of_voice + '.',
  'Палитра: ' + Object.keys(brief.brand.palette || {}).map(function (k) {
    return brief.brand.palette[k];
  }).join('; ') + '.',
  'Типографика: ' + brief.brand.typography + '.',
  'Логотип: ' + brief.brand.logo_rule + '.',
  '',
  'СЕГМЕНТЫ ЦА:',
  brief.segments.map(function (s) {
    return '- ' + s.id + ' ' + s.name + ': ' + s.who + '. Уровень: ' + s.current_level +
      '. Инсайт: ' + s.insight + '. Задача: ' + s.job_to_be_done + '. Сообщение: «' + s.message + '».';
  }).join('\n'),
  '',
  'ПЛОЩАДКИ:',
  brief.placements.map(function (p) {
    return '- ' + p.id + ' ' + p.name + ': ' + p.size + ' (' + p.ratio + '), безопасные поля ' +
      p.safe_zone + ', зона под текст — ' + p.text_zone + '. Контекст: ' + p.reading_context +
      '. Требования: ' + p.requirements + '.';
  }).join('\n'),
  '',
  'ВИЗУАЛЬНЫЙ ЯЗЫК:',
  'Базовый стиль: ' + brief.visual_language.style_base + '.',
  'Свет: ' + brief.visual_language.light + '.',
  'Композиция: ' + brief.visual_language.composition + '.',
  'Фокус: ' + brief.visual_language.focus + '.',
  'Акцент: ' + brief.visual_language.accent + '.',
  'Фотография: ' + brief.visual_language.photography + '.',
  '',
  'ВАРИАНТЫ, КОТОРЫЕ НУЖНО ОПИСАТЬ ПРОМТАМИ:',
  tasks.map(function (t) {
    return [
      '- ' + t.id + ': сегмент ' + t.segment_id + ' (' + t.segment_name + '), площадка ' +
        t.placement_id + ' (' + t.placement_name + ', ' + t.placement_size + ', ' + t.placement_ratio +
        ', зона под текст: ' + t.placement_text_zone + '), стиль: ' + t.style +
        ', фокус: ' + t.composition_focus + ', акцент: ' + t.accent + '.',
      t.changed_parameter ? '  ОСОБОЕ УСЛОВИЕ: ' + t.changed_parameter +
        '. Неизменно: ' + t.unchanged_parameters + '.' : ''
    ].filter(Boolean).join('\n');
  }).join('\n'),
  '',
  'ЗАПРЕЩЁННЫЕ ЭЛЕМЕНТЫ (их не должно быть на картинке):',
  brief.restrictions.forbidden_elements.map(function (f) { return '- ' + f; }).join('\n')
].join('\n');

return [{
  json: {
    brief_pack: pack,
    tasks: tasks,
    settings: settings,
    brief_summary: {
      campaign: brief.campaign,
      product: brief.product.name,
      brand: brief.brand.name,
      segments: brief.segments.length,
      placements: brief.placements.length,
      variants: tasks.length
    },
    fix_threshold: fixThreshold,
    parsed_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

// ============================================================================
// ШАГ 3. ПРОМТЫ ОТ LLM-АГЕНТА + ПРОВЕРКА ВАРИАТИВНОСТИ
// ----------------------------------------------------------------------------
// Забирает ответ агента-промт-инженера, разбирает JSON и склеивает его с
// параметрами вариантов из брифа. Здесь же — три предохранителя:
//
//   1. Если модель вернула мусор вместо JSON или промт слишком короткий —
//      берём запасной промт из брифа (он лежит в plan[].fallback_prompt).
//   2. Если в промте осталась кириллица или он не запрещает текст на картинке —
//      чиним принудительно, не доверяя модели.
//   3. Вариативность: промт альтернативы (V4) собирается НЕ заново, а заменой
//      одного фрагмента в промте базового варианта (V1). Так требование «изменён
//      ровно один параметр» выполняется конструктивно, а не по обещанию модели.
// ============================================================================

const src = $input.first().json;
const pack = $('Разобрать бриф').first().json;

const raw = String(
  (src.message && src.message.content) ? src.message.content :
  (src.content || src.text || src.output || '')
);

// --- вытаскиваем JSON из ответа модели --------------------------------------
// Модель-рассуждалка сначала печатает длинное размышление, а следом — JSON.
// Узел Ollama отдаёт и то и другое одной строкой, без разделителя, и в боевом
// ответе (прогон 83) начало объекта оказалось испорчено: вместо
// «…Let me finalize.{"variants":[…]}» пришло «…Let me finalize.variants":[…]}» —
// без открывающих `{"`, зато с лишней закрывающей `}`. Прямой разбор такого
// текста падал, узел молча уходил на запасные промты из брифа, и работа
// LLM-агента пропадала целиком. Поэтому разбор трёхступенчатый.

// Возвращает сбалансированный кусок текста от скобки start до парной ей,
// пропуская скобки внутри строк. null — если пары нет.
function balanced(s, start) {
  const open = s[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < s.length; i++) {
    const c = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === open) depth++;
    else if (c === close) {
      depth--;
      if (!depth) return s.slice(start, i + 1);
    }
  }
  return null;
}

function tryParse(s) {
  try { return JSON.parse(s); } catch (e) { return null; }
}

function extractJson(t) {
  const cleaned = t.replace(/```json/gi, '```').split('```').join('\n');

  // 1. Обычный случай: от первой `{` до последней `}`. Требуем массив
  //    вариантов: если в прозе попался корректный, но посторонний объект,
  //    он не должен подменять собой ответ (иначе узел снова уйдёт на запасной
  //    промт, хотя разбираемый ответ в тексте есть).
  const a = cleaned.indexOf('{');
  const b = cleaned.lastIndexOf('}');
  if (a >= 0 && b > a) {
    const p = tryParse(cleaned.slice(a, b + 1));
    if (p && Array.isArray(p.variants)) return p;
  }

  // 2. Испорченное начало массива вариантов. Массив при этом целый, поэтому
  //    берём любой сбалансированный массив, элементы которого похожи на
  //    варианты (объекты с полем id), и собираем объект заново — имя ключа
  //    восстанавливаем сами, в тексте от него мог остаться только хвост.
  for (let i = cleaned.indexOf('['); i >= 0; i = cleaned.indexOf('[', i + 1)) {
    const piece = balanced(cleaned, i);
    if (!piece) continue;
    const arr = tryParse(piece);
    if (!Array.isArray(arr) || !arr.length) continue;
    const looksLikeVariants = arr.every(function (v) {
      return v && typeof v === 'object' && !Array.isArray(v) && v.id;
    });
    if (looksLikeVariants) return { variants: arr };
  }

  // 3. Последняя попытка: перебираем все `{` и берём первый сбалансированный
  //    кусок, в котором есть массив вариантов.
  for (let i = cleaned.indexOf('{'); i >= 0; i = cleaned.indexOf('{', i + 1)) {
    const piece = balanced(cleaned, i);
    if (!piece) continue;
    const p = tryParse(piece);
    if (p && Array.isArray(p.variants)) return p;
  }

  return null;
}

const parsed = extractJson(raw);
const byId = {};
if (parsed && Array.isArray(parsed.variants)) {
  parsed.variants.forEach(function (v) {
    if (v && v.id) byId[String(v.id).toUpperCase()] = v;
  });
}

// Диагностика ответа агента: попадает в реестр, чтобы при разборе полётов было
// видно, что именно вернула модель.
const agentDiag = {
  agent_answer_chars: raw.length,
  agent_json_ok: !!(parsed && Array.isArray(parsed.variants)),
  agent_variants: Object.keys(byId),
  agent_input_keys: Object.keys(src).join(','),
  agent_answer_head: (parsed && Array.isArray(parsed.variants)) ? null : raw.slice(0, 800)
};

const NO_TEXT_CLAUSE = 'no text, no letters, no numbers, no words, no watermark, no logo';

function sane(text, id) {
  const p = String(text || '').trim().replace(/\s+/g, ' ').replace(/^["'«]|["'»]$/g, '');
  if (p.length < 60) return null;                 // слишком короткий — это не промт
  if (/[А-Яа-яЁё]/.test(p)) return null;          // промт должен быть на английском
  if (!/prompt|photo|photograph|illustration|image|scene|shot/i.test(p)) return null;
  if (!/no text/i.test(p)) return p + ', ' + NO_TEXT_CLAUSE;
  return p;
}

const items = pack.tasks.map(function (t) {
  const task = Object.assign({}, t);
  const fromModel = byId[task.id];
  let warning = null;

  // Имя файла задаём сразу и здесь, а не по ходу дела: узел сохранения берёт
  // его выражением {{ $json.file_name }} и без этого писал один и тот же
  // «undefined.webp» на все варианты. Расширение условное — оба генератора
  // (ссылка и base64) переписывают его по фактическому формату картинки.
  task.file_name = task.id + '-a' + (task.attempt || 1) + '.webp';

  if (fromModel) {
    const p = sane(fromModel.prompt, task.id);
    if (p) {
      task.prompt = p;
      task.prompt_source = 'llm';
    } else {
      warning = 'Промт от модели не прошёл проверку — взят запасной промт из брифа';
    }
    task.negative = String(fromModel.negative || '').trim();
    task.rationale = String(fromModel.rationale || '').trim();
    if (fromModel.style_swap) task.style_swap = fromModel.style_swap;
  } else {
    warning = 'Модель не вернула вариант ' + task.id + ' — взят запасной промт из брифа';
  }

  task.prompt_warning = warning;
  Object.assign(task, agentDiag);
  return task;
});

// --- вариативность: альтернатива = базовый вариант с одной заменой ----------
const byVariant = {};
items.forEach(function (t) { byVariant[t.id] = t; });

items.forEach(function (t) {
  if (!t.base_variant) return;
  const base = byVariant[t.base_variant];
  const swap = t.style_swap;
  let applied = false;

  if (base && swap && swap.from && swap.to) {
    const from = String(swap.from).trim();
    const to = String(swap.to).trim();
    const idx = base.prompt.toLowerCase().indexOf(from.toLowerCase());
    if (idx >= 0) {
      t.prompt = base.prompt.slice(0, idx) + to + base.prompt.slice(idx + from.length);
      t.prompt_source = 'llm (замена одного фрагмента в ' + t.base_variant + ')';
      applied = true;
      // Модель для альтернативы намеренно не пишет полный промт — только пару
      // style_swap. Поэтому проверка «промт не прошёл» выше срабатывает всегда;
      // раз замена удалась, предупреждение снимаем, иначе оно врёт в реестре.
      t.prompt_warning = null;
    }
  }

  if (!applied) {
    // Замена не удалась — берём запасной промт альтернативы и запрещаем
    // считать это «изменением одного параметра» по факту.
    t.prompt = sane(t.fallback_prompt, t.id) || t.prompt;
    t.prompt_source = 'fallback';
    t.prompt_warning = 'Фрагмент стиля не найден в промте ' + t.base_variant +
      ' — альтернатива сгенерирована по запасному промту. Различие параметров проверено вручную.';
  }

  t.seed = base ? base.seed : t.seed;   // сид принудительно тот же
  t.variativity_applied = applied;
});

return items.map(function (t) { return { json: t }; });

// ============================================================================
// ШАГ 4. ГЕНЕРАЦИЯ ИЗОБРАЖЕНИЙ
// ----------------------------------------------------------------------------
// Бесплатные публичные генераторы живут неровно, поэтому эшелонов три.
//
//   1) Быстрый эшелон — публичные спейсы Hugging Face на ZeroGPU
//      (FLUX.1-merged, Kolors, FLUX.1-dev). Отдают ссылку за секунды, но
//      квота у них на IP, а не на запрос: когда она выбрана, все три спейса
//      отвечают «event: error / data: null» за пару секунд. Поэтому спейсы
//      проверяются ОДНИМ пробным запросом на первом же варианте, а не
//      двадцатью четырьмя, как было бы при переборе по каждому варианту.
//   2) Основной эшелон — Stable Horde, краудсорсинг-сеть воркеров. Ключ не
//      нужен (анонимный '0000000000'), квоты нет, отдаёт base64. Но очередь
//      анонимного клиента тем длиннее, чем «дороже» задание: у задачи на
//      512x512 она стартует сразу, у 1024x1024 может стоять сотни позиций.
//      В часы нагрузки сервис вдобавок закрывает крупные запросы порогом
//      «заслуг»: «Due to heavy demand, for requests over 1024x1024 or over the
//      applicable first-order-equivalent sampler work budget the client needs to
//      already have the required kudos» (замер tools/horde-queue-probe.py:
//      задача 1024x1024 у SDXL 1.0 стояла 295-й, а та же сцена 512x512 —
//      нулевой). Порог считается по площади и числу шагов, поэтому список из
//      нескольких SDXL-моделей его тоже перешагивает: он оценивается дороже
//      одной модели (20.03 против 18.0) и был отклонён. Отсюда правило: у
//      основного эшелона ровно одна модель, а лёгкий запас — рабочий путь, а
//      не редкая страховка (в прогоне 86 тяжёлый размер так и не дошёл).
//   3) Лёгкий запас — если за HORDE_FAST_AFTER_MS ни одна задача основного
//      эшелона не сдвинулась с места, недостающие варианты досылаются в
//      уменьшенном размере с меньшим числом шагов. Первичные задачи при этом
//      продолжают опрашиваться: что придёт раньше — то и пойдёт в результат.
//      Фактический размер пишется в поле size_actual.
//
// Pollinations.ai (вариант, который пробовали первым) в работу не годится:
// на любой новый запрос отвечает 402 Payment Required, картинку отдаёт только
// из кэша — проверено tools/horde-size-test.py и отдельной пробой параметров.
//
// ВАЖНО про бинарные данные: Code-узел в этом n8n НЕ умеет скачивать бинарник
// по сети — helpers.httpRequest отдаёт побитую строку (проверено диагностикой
// tools/probe-binary-roundtrip.py: 28710 «байт» вместо 30320). Зато base64,
// полученный как обычный JSON, Code-узел превращает в настоящий файл без потерь
// (md5 совпадает). Поэтому:
//   • быстрый эшелон отдаёт ССЫЛКУ  -> её скачивает узел HTTP Request;
//   • Stable Horde отдаёт BASE64     -> его собирает узел «Картинка из base64».
// Дальше ветки сходятся на узле сохранения файла.
// ============================================================================

const H = this.helpers;
const items = $input.all();

function sleep(ms) {
  return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

function msg(e) {
  return String((e && e.message) || e);
}

// --- эшелон 1: публичные спейсы Hugging Face --------------------------------
const HF_PROVIDERS = [
  {
    name: 'FLUX.1-merged (multimodalart)',
    host: 'https://multimodalart-flux-1-merged.hf.space',
    endpoint: '/infer',
    body: function (t) { return { data: [t.prompt, t.seed, false, t.width, t.height, 3.5, 4] }; }
  },
  {
    name: 'Kolors (Kwai)',
    host: 'https://kwai-kolors-kolors.hf.space',
    endpoint: '/infer',
    body: function (t) {
      return { data: [t.prompt, null, 0.5, negativeFor(t), t.seed, false, t.width, t.height, 5.0, 25] };
    }
  },
  {
    name: 'FLUX.1-dev (black-forest-labs)',
    host: 'https://black-forest-labs-flux-1-dev.hf.space',
    endpoint: '/infer',
    body: function (t) { return { data: [t.prompt, t.seed, false, t.width, t.height, 3.5, 4] }; }
  }
];

async function hfOnce(provider, t) {
  const call = await H.httpRequest({
    url: provider.host + '/gradio_api/call' + provider.endpoint,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: provider.body(t),
    json: true,
    timeout: 30000
  });

  const eventId = call && call.event_id;
  if (!eventId) throw new Error('спейс не вернул event_id');

  const stream = await H.httpRequest({
    url: provider.host + '/gradio_api/call' + provider.endpoint + '/' + eventId,
    method: 'GET',
    encoding: 'utf8',
    timeout: 180000
  });

  const text = String(stream || '');
  if (/event:\s*error/.test(text)) {
    throw new Error('спейс отклонил задание (квота ZeroGPU или ошибка модели)');
  }
  const m = text.match(/"url"\s*:\s*"([^"]+)"/);
  if (!m) throw new Error('в ответе спейса нет ссылки на картинку');
  return m[1];
}

// --- эшелон 2 и 3: Stable Horde ---------------------------------------------
const HORDE_API = 'https://stablehorde.net/api/v2';
const HORDE_KEY = '0000000000';   // анонимный ключ Stable Horde
const HORDE_MODEL = 'SDXL 1.0';

// Модели для лёгкого запаса — с родным разрешением 512 (SD 1.5-финетюны).
// SDXL 1.0 рассчитан на 1024: на 512x512 он уходит в плоскую стилизацию, и
// «запасная» картинка получается абстрактной — в прогоне 82 так вышли V1 и V3,
// чек-лист поставил им 4 и 3 «нет» именно за это.
//
// Base-модель stable_diffusion из списка убрана: в прогоне 86 она нарисовала
// «руки над блокнотом» вместо героини в кадре и куклу вместо женщины у стола,
// и чек-лист справедливо поставил этим вариантам «нет» за соответствие брифу.
// Замер на одном и том же промте (tools/horde-model-pick.py, 512x512, 30 шагов)
// показал, что финетюны держат сцену, а base-модель её теряет. AbsoluteReality
// стоит первым: у него кадр совпал с брифом лучше всех — героиня в тёмно-синем
// костюме с оранжевым акцентом, брендовая палитра и свободная левая половина.
// Порядок в списке — приоритет: Stable Horde берёт первую модель, воркер
// которой свободен.
const HORDE_MODELS_FAST = ['AbsoluteReality', 'Realistic Vision', 'Deliberate'];
const HORDE_POLL_MS = 15000;
const HORDE_MAX_WAIT_MS = 35 * 60 * 1000;   // общий потолок ожидания очереди
// Столько ждём «тяжёлый» размер, прежде чем досылать лёгкий. Замер на боевых
// конфигурациях (tools/horde-size-test.py): задача 1024x1024 у анонимного
// клиента стояла 189-й в общей очереди и за 15 минут не сдвинулась, а та же
// сцена в 512x512 на модели с родным разрешением 512 стартовала сразу
// (queue_position 0, 13 свободных воркеров) и была готова за 1,9 минуты.
const HORDE_FAST_AFTER_MS = 3 * 60 * 1000;
// Анонимному клиенту сервис разрешает около одного запроса в секунду и отвечает
// 429, если частить. Паузы держим и между отправками, и между опросами: иначе
// пачка проверок «съедает» лимит, отправка лёгкого размера падает, и узел
// честно ждёт тяжёлую очередь до самого потолка.
const HORDE_GAP_MS = 1500;
const HORDE_POLL_GAP_MS = 400;
// Окно на «повышение» размера. Цикл выходит, как только закрылась последняя
// дырка, поэтому лёгкая картинка успевала проскочить раньше тяжёлой и оставалась
// в результате навсегда — тяжёлая задача при этом ещё стояла в очереди и её
// никто не ждал. Теперь после сборки всех вариантов даём живым тяжёлым задачам
// ещё немного времени: что успело — заменит лёгкую картинку.
const HORDE_UPGRADE_GRACE_MS = 8 * 60 * 1000;

// Воркеры Stable Horde берут размеры, кратные 64. Пропорции площадок держим
// точно, а по площади не выходим за 1024x1024: у анонимного клиента запрос
// крупнее требует «заслуг» (KudosUpfront).
const HORDE_SIZES = {
  '1:1': [1024, 1024],
  '4:5': [768, 960],
  '3:4': [768, 1024],
  '4:3': [1024, 768],
  '16:9': [1024, 576]
};

// Лёгкий запас: те же пропорции, но маленькая площадь — такие задачи анонимной
// очереди стартуют почти сразу.
const HORDE_SIZES_FAST = {
  '1:1': [512, 512],
  '4:5': [512, 640],
  '3:4': [512, 640],
  '4:3': [512, 384],
  '16:9': [576, 320]
};

// Английский список запретов, собранный из restrictions.forbidden_elements
// брифа. Это не только запасной вариант: генератор понимает английские слова,
// поэтому русский negative из брифа ему бесполезен (см. negativeFor ниже).
const DEFAULT_NEGATIVE = 'text, letters, numbers, words, captions, watermark, ' +
  'logo, signature, brand logos, apple logo, laptop logo, headset logo, ' +
  'device brand marks, stickers on devices, flags, coats of arms, maps, ' +
  'political or religious symbols, Big Ben, red double-decker bus, cup of tea, ' +
  'royal guard, Tower Bridge, children, teenagers, school chalkboard, ' +
  'celebrities, real people, alcohol, tobacco, weapons, blood, gambling, drugs, ' +
  'medical masks, disasters, nudity, distorted face, extra fingers, fused ' +
  'fingers, deformed limbs, low quality, blurry, jpeg artifacts, collage, ' +
  'frame, gradient stock background';

// SDXL и другие диффузионные модели работают через английский CLIP: русские
// слова для них — не текст, а случайные токены, то есть запретов становится ноль.
// Агент писал negative по-русски (так же, как сформулированы запреты в брифе),
// и в генератор уходил неработающий набор. Поэтому здесь проверяем язык: если
// кириллица есть — берём английский список, а исходный текст сохраняем для
// реестра отдельным полем.
function negativeFor(t) {
  const n = String(t.negative || '');
  if (n.length > 3 && !/[А-Яа-яЁё]/.test(n)) return n;
  return DEFAULT_NEGATIVE;
}

async function horde(path, method, body) {
  const options = {
    url: HORDE_API + path,
    method: method,
    headers: {
      apikey: HORDE_KEY,
      'Client-Agent': 'n8n-visual-creatives:1.0:anonymous',
      'Content-Type': 'application/json'
    },
    json: true,
    timeout: 60000
  };
  if (body) options.body = body;
  return await H.httpRequest(options);
}

function hordeBody(t, size, steps, models) {
  return {
    prompt: t.prompt,
    params: {
      width: size[0],
      height: size[1],
      steps: steps,
      cfg_scale: 7,
      sampler_name: 'k_euler_a',
      n: 1,
      seed: String(t.seed === undefined || t.seed === null ? 0 : t.seed),
      negative_prompt: negativeFor(t)
    },
    nsfw: false,
    censor_nsfw: true,
    trusted_workers: false,
    slow_workers: true,
    models: models || [HORDE_MODEL],
    r2: false
  };
}

function sniffImage(buf) {
  if (buf[0] === 0x89 && buf[1] === 0x50) return { mime: 'image/png', ext: 'png' };
  if (buf[0] === 0xFF && buf[1] === 0xD8) return { mime: 'image/jpeg', ext: 'jpg' };
  if (buf[0] === 0x52 && buf[1] === 0x49) return { mime: 'image/webp', ext: 'webp' };
  return { mime: 'image/png', ext: 'png' };
}

// --- эшелон 1: быстрые спейсы -----------------------------------------------
const result = [];
const errors = [];

if (items.length) {
  // Квота у спейсов одна на IP, поэтому сначала один пробный запрос: если он
  // не прошёл — перебирать остальные варианты бессмысленно и долго.
  let hfProvider = null;
  for (const provider of HF_PROVIDERS) {
    try {
      result[0] = { url: await hfOnce(provider, items[0].json), provider: provider.name, attempt: 1 };
      hfProvider = provider;
      break;
    } catch (e) {
      errors.push(items[0].json.id + ' | проверка ' + provider.name + ': ' + msg(e));
      await sleep(1000);
    }
  }

  if (hfProvider) {
    for (let i = 1; i < items.length; i++) {
      try {
        result[i] = { url: await hfOnce(hfProvider, items[i].json), provider: hfProvider.name, attempt: 1 };
      } catch (e) {
        errors.push(items[i].json.id + ' | ' + hfProvider.name + ': ' + msg(e));
      }
    }
  }
}

// --- эшелоны 2 и 3: Stable Horde --------------------------------------------
const needHorde = [];
for (let i = 0; i < items.length; i++) {
  if (!result[i]) needHorde.push(i);
}

const hordeNote = [];

if (needHorde.length) {
  const jobs = [];        // {id, index, size, fast, taken}
  const pending = {};     // id -> job

  async function submitJob(idx, fast) {
    const t = items[idx].json;
    const table = fast ? HORDE_SIZES_FAST : HORDE_SIZES;
    const size = table[t.placement_ratio] || (fast ? HORDE_SIZES_FAST['1:1'] : HORDE_SIZES['1:1']);
    const models = fast ? HORDE_MODELS_FAST : [HORDE_MODEL];
    try {
      const sub = await horde('/generate/async', 'POST', hordeBody(t, size, fast ? 30 : 25, models));
      if (!sub || !sub.id) throw new Error('сервис не вернул id задания');
      const job = { id: sub.id, index: idx, size: size, fast: fast, models: models, taken: false };
      jobs.push(job);
      pending[sub.id] = job;
      return true;
    } catch (e) {
      errors.push(t.id + ' | Stable Horde (отправка ' + size[0] + 'x' + size[1] + '): ' + msg(e));
      return false;
    }
  }

  const startedAt = Date.now();
  const missing = function () {
    return needHorde.filter(function (i) { return !result[i]; });
  };

  for (const idx of needHorde) {
    await submitJob(idx, false);
    await sleep(HORDE_GAP_MS);
  }

  let fastSwitched = false;
  const faulted = {};
  const fastTries = {};

  // Варианты, которые уже закрыты лёгкой картинкой, но у которых тяжёлая задача
  // ещё жива: ради них и держим окно ожидания.
  const upgradeable = function () {
    const list = [];
    for (let i = 0; i < items.length; i++) {
      const r = result[i];
      if (!r || !r.fast) continue;
      const alive = jobs.some(function (j) {
        return j.index === i && !j.fast && pending[j.id];
      });
      if (alive) list.push(i);
    }
    return list;
  };

  let upgradeDeadline = null;

  while (Date.now() - startedAt < HORDE_MAX_WAIT_MS) {
    if (!missing().length) {
      const waiting = upgradeable();
      if (!waiting.length) break;
      if (upgradeDeadline === null) {
        upgradeDeadline = Date.now() + HORDE_UPGRADE_GRACE_MS;
        hordeNote.push('лёгкие картинки собраны, ждём тяжёлый размер ещё ' +
          Math.round(HORDE_UPGRADE_GRACE_MS / 60000) + ' мин: ' +
          waiting.map(function (i) { return items[i].json.id; }).join(', '));
      }
      if (Date.now() > upgradeDeadline) break;
    }
    await sleep(HORDE_POLL_MS);

    let moving = 0;
    for (const id of Object.keys(pending)) {
      const job = pending[id];
      const have = result[job.index];
      // Готовый результат — не повод бросить задачу: лёгкая картинка уже есть,
      // но тяжёлую мы всё ещё ждём, чтобы она её заменила. Раньше здесь стояла
      // проверка «result есть — удалить», и тяжёлая задача пропадала из pending
      // в тот же круг, как приходила лёгкая. Окно ожидания после этого не
      // находило живых тяжёлых задач и закрывалось мгновенно.
      if (have && (job.fast || !have.fast)) { delete pending[id]; continue; }
      try {
        const check = await horde('/generate/check/' + id, 'GET');
        if (!check) continue;
        if (check.done) {
          // забираем картинку
          const status = await horde('/generate/status/' + id, 'GET');
          const gen = (status && status.generations && status.generations[0]) ? status.generations[0] : null;
          if (gen && gen.img) {
            const buf = Buffer.from(gen.img, 'base64');
            if (buf.length) {
              // тяжёлый размер важнее лёгкого: если место ещё свободно — берём его
              if (!result[job.index] || (result[job.index].fast && !job.fast)) {
                const kind = sniffImage(buf);
                result[job.index] = {
                  base64: gen.img,
                  provider: 'Stable Horde (' + (gen.model || HORDE_MODEL) + ')',
                  ext: kind.ext,
                  mime: kind.mime,
                  bytes: buf.length,
                  seed: gen.seed,
                  fast: job.fast,
                  size: job.size
                };
                hordeNote.push(items[job.index].json.id + ': ' + String(gen.model || HORDE_MODEL) +
                  ' ' + job.size[0] + 'x' + job.size[1]);
              }
            } else {
              errors.push(items[job.index].json.id + ' | Stable Horde: картинка не декодировалась');
            }
          } else {
            errors.push(items[job.index].json.id + ' | Stable Horde: пустой ответ без картинки');
          }
          delete pending[id];
          continue;
        }
        if (check.faulted) {
          if (!faulted[job.index]) {
            errors.push(items[job.index].json.id + ' | Stable Horde (' + job.size[0] + 'x' + job.size[1] +
              '): задание отклонено');
            faulted[job.index] = true;
          }
          delete pending[id];
          continue;
        }
        const q = check.queue_position;
        if (check.processing || (typeof q === 'number' && q < 40)) moving++;
      } catch (e) {
        // одиночный сбой опроса не должен ронять весь цикл
      }
      await sleep(HORDE_POLL_GAP_MS);
    }

    // Лёгкий запас: тяжёлые задачи стоят в очереди — досылаем уменьшенные.
    // Отправка может не пройти (лимит запросов, сбой сети), поэтому пробуем
    // в каждом круге опроса, пока у варианта нет ни лёгкой задачи, ни картинки.
    if (Date.now() - startedAt > HORDE_FAST_AFTER_MS && missing().length) {
      if (!fastSwitched) {
        fastSwitched = true;
        hordeNote.push('включён лёгкий размер (в очереди оставалось ' +
          jobs.filter(function (j) { return !faulted[j.index]; }).length + ' задач)');
      }
      for (const idx of missing()) {
        const hasFast = jobs.some(function (j) {
          return j.index === idx && j.fast && pending[j.id];
        });
        if (hasFast) continue;
        // пять попыток на вариант: если сервис стабильно отказывает,
        // долбить его каждые 15 секунд до потолка бессмысленно
        fastTries[idx] = (fastTries[idx] || 0);
        if (fastTries[idx] >= 5) continue;
        fastTries[idx]++;
        await submitJob(idx, true);
        await sleep(HORDE_GAP_MS);
      }
    }
  }

  const still = missing();
  if (still.length) {
    errors.push('Stable Horde: за ' + Math.round(HORDE_MAX_WAIT_MS / 60000) +
      ' мин не дождались картинок для: ' + still.map(function (i) { return items[i].json.id; }).join(', '));
  }

  // Окно закрылось, а тяжёлые задачи так и не дошли: фиксируем это в реестре,
  // чтобы «size_downgraded: true» не выглядел случайностью.
  const notUpgraded = upgradeable();
  if (notUpgraded.length) {
    hordeNote.push('тяжёлый размер не догнал за окно ожидания: ' +
      notUpgraded.map(function (i) { return items[i].json.id; }).join(', ') + ' — оставлен лёгкий');
  }
}

// --- собираем результат ------------------------------------------------------
const out = [];

for (let i = 0; i < items.length; i++) {
  const t = Object.assign({}, items[i].json);
  const r = result[i];

  if (!r) {
    throw new Error('Ни один генератор не отдал изображение для варианта ' + t.id + '. ' +
      errors.join(' | '));
  }

  t.generator = r.provider;
  t.generator_attempt = r.attempt || 1;
  t.generator_errors = errors.slice();
  // Заметки по ходу ожидания (какой размер, что успело дойти) — раньше они
  // копились в массиве и никуда не попадали: в реестре не было видно, почему
  // у креатива понижен размер.
  t.generator_note = hordeNote.slice();
  // Что именно ушло в генератор как запрет и почему: если negative_used не
  // совпадает с negative из ответа агента, значит исходный был на кириллице и
  // модель его всё равно не поняла.
  t.negative_used = negativeFor(t);
  t.negative_source = (t.negative_used === String(t.negative || ''))
    ? 'ответ агента' : 'английский список из брифа (ответ агента был на русском)';
  t.generated_at = $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss');

  if (r.url) {
    // быстрый эшелон: картинку скачает следующий узел HTTP Request
    t.image_url = r.url;
    t.image_b64 = null;
    t.image_delivery = 'url';
    t.size_actual = t.width + 'x' + t.height;
  } else {
    // Stable Horde: base64 -> бинарник соберёт узел «Картинка из base64»
    t.image_url = null;
    t.image_b64 = r.base64;
    t.image_delivery = 'base64';
    t.image_mime = r.mime;
    t.file_name = String(t.file_name).replace(/\.[a-z0-9]+$/i, '') + '.' + r.ext;
    if (r.seed !== undefined && r.seed !== null) t.seed_actual = r.seed;
    t.size_actual = r.size[0] + 'x' + r.size[1];
    t.size_downgraded = !!r.fast;
    t.width = r.size[0];
    t.height = r.size[1];
  }

  out.push({ json: t });
}

return out;

// ============================================================================
// ШАГ 4б. КАРТИНКА ИЗ BASE64 (ветка запасного генератора)
// ----------------------------------------------------------------------------
// Нужен для Stable Horde: он отдаёт не ссылку, а картинку в base64 внутри JSON.
// Code-узел не умеет тянуть бинарник из сети, но base64 -> файл он собирает
// без потерь: проверено диагностикой tools/probe-binary-roundtrip.py —
// md5 записанного файла совпадает с исходным.
//
// Тип файла определяем по «магическим» байтам, а не по расширению: воркеры
// Stable Horde отдают то webp, то png, то jpg.
// ============================================================================

const H = this.helpers;
const items = $input.all();
const out = [];

function sniffImage(buf) {
  if (buf[0] === 0x89 && buf[1] === 0x50) return { mime: 'image/png', ext: 'png' };
  if (buf[0] === 0xFF && buf[1] === 0xD8) return { mime: 'image/jpeg', ext: 'jpg' };
  if (buf[0] === 0x52 && buf[1] === 0x49) return { mime: 'image/webp', ext: 'webp' };
  return { mime: 'image/png', ext: 'png' };
}

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;

  if (!j.image_b64) {
    throw new Error('Нет base64-изображения для варианта ' + j.id + ' — ветка вызвана ошибочно.');
  }

  const buf = Buffer.from(j.image_b64, 'base64');
  if (!buf.length) {
    throw new Error('Base64-изображение варианта ' + j.id + ' не декодировалось.');
  }

  const kind = sniffImage(buf);
  const fileName = String(j.file_name).replace(/\.[a-z0-9]+$/i, '') + '.' + kind.ext;
  const bin = await H.prepareBinaryData(buf, fileName, kind.mime);

  const next = Object.assign({}, j, {
    file_name: fileName,
    image_mime: kind.mime,
    image_bytes: buf.length,
    image_kb: Math.round(buf.length / 1024)
  });
  delete next.image_b64;   // дальше картинка живёт в binary, base64 в JSON не нужен

  out.push({ json: next, binary: { data: bin } });
}

return out;

// ============================================================================
// ШАГ 5. ЗАПРОС К VISION-МОДЕЛИ
// ----------------------------------------------------------------------------
// Готовит тело запроса к Ollama: промт проверки и картинку в base64.
//
// ВАЖНО про бинарные данные. В этом n8n бинарники хранятся в файловом режиме
// (N8N_DEFAULT_BINARY_DATA_MODE=filesystem): в поле binary.data.data лежит не
// base64-строка, а короткая ссылка вида "filesystem-v2". Поэтому байты надо
// доставать хелпером getBinaryDataBuffer — он возвращает настоящий Buffer
// внутри Code-узла, и уже его переводим в base64.
// (Проверено диагностикой tools/probe-binary.py: ссылка длиной 13 символов
//  против 40826 байт у getBinaryDataBuffer.)
// ============================================================================

const H = this.helpers;
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const bin = (items[i].binary && items[i].binary.data) ? items[i].binary.data : null;

  if (!bin) {
    throw new Error('Нет бинарных данных изображения для варианта ' + j.id + ' (' + j.file_name + ')');
  }

  let b64 = null;
  let bytes = 0;
  try {
    const buf = await H.getBinaryDataBuffer(i, 'data');
    if (Buffer.isBuffer(buf) && buf.length > 0) {
      b64 = buf.toString('base64');
      bytes = buf.length;
    }
  } catch (e) {
    throw new Error('Не удалось прочитать байты изображения ' + j.file_name + ': ' +
      String((e && e.message) || e));
  }

  if (!b64) {
    throw new Error('Пустые байты изображения ' + j.file_name);
  }

  const st = j.settings || {};

  const prompt = [
    'Ты — арт-директор онлайн-школы английского языка. Оцени готовый рекламный креатив по чек-листу заказчика.',
    '',
    j.vision_context,
    '',
    'ПРОВЕРЯЕМЫЙ ВАРИАНТ ' + j.id + ':',
    'Сегмент ЦА: ' + j.segment_id + ' — ' + j.segment_name + '. ' + j.segment_who + '. Инсайт: ' + j.segment_insight + '.',
    'Площадка: ' + j.placement_id + ' — ' + j.placement_name + ', ' + j.placement_size + ' (' + j.placement_ratio + '), зона под текст: ' + j.placement_text_zone + '.',
    'Заявленный стиль: ' + j.style + '. Фокус: ' + j.composition_focus + '. Акцент: ' + j.accent + '.',
    'Задание генератору (промт): ' + j.prompt,
    '',
    'ЧЕК-ЛИСТ — ответь «да» или «нет» по каждому пункту:',
    '1. brief — соответствие брифу, бренду и площадке: сюжет и настроение совпадают с описанием, пропорция и композиция подходят площадке, зона под будущий текст действительно свободна, цвета согласуются с палитрой бренда и заявленным стилем.',
    '2. audience — релевантность ЦА: изображённый человек и ситуация выглядят как описанный сегмент (возраст, контекст, уровень жизни), не вызывают отторжения у этой аудитории.',
    '3. forbidden — отсутствие запрещённых элементов: на картинке нет текста, букв и цифр, логотипов и водяных знаков, флагов и политической символики, стереотипов об Англии, детей, алкоголя, оружия, искажённых лиц и лишних пальцев.',
    '4. quality — техническое качество: композиция читается, изображение резкое, нет артефактов генерации, креатив пригоден для публикации в ленте.',
    '',
    'Ответь СТРОГО одним JSON-объектом, без markdown и без текста вокруг:',
    '{"brief":"да|нет","audience":"да|нет","forbidden":"да|нет","quality":"да|нет","comment":"1-2 предложения: что изображено и общее впечатление","improve":"одно предложение, что конкретно поправить, если есть «нет»; иначе — правки не нужны"}'
  ].join('\n');

  out.push({
    json: Object.assign({}, j, {
      ollama_model: st.vision_model || 'deepseek-v4.1-flash:cloud',
      vision_temperature: (st.vision_temperature === undefined ? 0.1 : st.vision_temperature),
      vision_prompt: prompt,
      image_b64: b64,
      image_bytes: bytes,
      image_kb: Math.round(bytes / 1024)
    })
  });
}

return out;

// ============================================================================
// ШАГ 6. ОЦЕНКА ПО ЧЕК-ЛИСТУ
// ----------------------------------------------------------------------------
// Разбирает ответ vision-модели и превращает его в четыре пункта чек-листа —
// ровно те, что стоят в шаблоне задания:
//   • соответствие брифу, бренду, площадке;
//   • релевантность ЦА;
//   • отсутствие запрещённых элементов;
//   • техническое качество.
//
// Метаданные варианта берём из узла Собрать запрос к Vision: узел HTTP Request с ответом Ollama
// подменяет json целиком, поэтому «своих» полей в текущем элементе уже нет.
//
// Здесь же решается, нужна ли правка: по условию задания креатив уходит на
// повторную генерацию, только если ответов «нет» БОЛЬШЕ ДВУХ (то есть 3 или 4).
// ============================================================================

const SRC = $('Собрать запрос к Vision').all();
const items = $input.all();
const MAX_ATTEMPT = 2;

const CHECK = [
  { key: 'brief', label: 'соответствие брифу, бренду, площадке;' },
  { key: 'audience', label: 'релевантность ЦА' },
  { key: 'forbidden', label: 'отсутствие запрещённых элементов' },
  { key: 'quality', label: 'техническое качество.' }
];

function yesNo(value) {
  if (typeof value === 'boolean') return value ? 'да' : 'нет';
  const s = String(value === undefined || value === null ? '' : value).trim().toLowerCase();
  if (!s) return 'нет';
  if (/^(да|yes|true|1|ok|ок)/.test(s)) return 'да';
  return 'нет';
}

function parseModelJson(text) {
  const t = String(text || '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try {
    return JSON.parse(t.slice(a, b + 1));
  } catch (e) {
    return null;
  }
}

const out = [];

for (let i = 0; i < items.length; i++) {
  const meta = (SRC[i] && SRC[i].json) ? SRC[i].json : {};
  const st = meta.settings || {};
  const threshold = (st.fix_threshold === undefined) ? 2 : Number(st.fix_threshold);
  const attempt = Number(meta.attempt || 1);

  const answer = parseModelJson(items[i].json.response);
  const visionError = items[i].json.error || null;

  const checklist = CHECK.map(function (c) {
    return {
      key: c.key,
      label: c.label,
      answer: answer ? yesNo(answer[c.key]) : 'н/д'
    };
  });

  const noCount = checklist.filter(function (c) { return c.answer === 'нет'; }).length;
  const naCount = checklist.filter(function (c) { return c.answer === 'н/д'; }).length;

  // Правка нужна, только если чек-лист реально заполнен, «нет» больше порога
  // и попытки ещё остались.
  const needsFix = !!answer && noCount > threshold && attempt < MAX_ATTEMPT;

  out.push({
    json: Object.assign({}, meta, {
      attempt: attempt,
      checklist: checklist,
      no_count: noCount,
      na_count: naCount,
      fix_threshold: threshold,
      needs_fix: needsFix,
      max_attempt: MAX_ATTEMPT,
      vision_ok: !!answer,
      vision_error: answer ? null : String(visionError || 'модель не вернула разбираемый JSON').slice(0, 200),
      vision_comment: answer ? String(answer.comment || '').trim() : '',
      vision_improve: answer ? String(answer.improve || '').trim() : '',
      vision_raw: answer ? null : String(items[i].json.response || '').slice(0, 400),
      vision_error_dump: answer ? null : JSON.stringify(items[i].json).slice(0, 1500),
      evaluated_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss')
    })
  });
}

return out;

// ============================================================================
// ШАГ 7. ИСПРАВЛЕНИЕ ПРОМТА
// ----------------------------------------------------------------------------
// Сюда попадают только те креативы, у которых в чек-листе больше двух «нет».
// Дописываем в промт ровно то, на что указал чек-лист, — по одному блоку
// уточнений на каждый проваленный пункт. Ничего другого не меняем, чтобы
// правка осталась правкой, а не новой генерацией «с нуля».
//
// Сид НЕ меняем. Раньше здесь стоял новый сид (`seed + 1000 × попытка`) с
// объяснением «иначе выйдет почти та же картинка». Объяснение верное, но цена
// оказалась выше: по заданию альтернатива V4 — это V1 с изменённым ровно одним
// параметром (стилем), и сид для неё копируется от V1 принудительно. Как только
// правка уводила сид, пара V1/V4 расходилась по кадру, и «чем отличается
// результат» описывал уже не разницу стилей, а две разные сцены. В прогоне 87
// V1 попал в правку, V4 — нет, и сравнивать их стало нечем.
// Теперь правка меняет только текст промта: кадр остаётся тем же, а уточнения
// по проваленным пунктам чек-листа — то, ради чего правка и делалась. Победившую
// попытку выбирает реестр: если правка не помогла, остаётся исходный вариант.
//
// ВАЖНО про язык уточнений. Раньше блоки собирались из русских полей брифа
// (стиль, зона под текст, портрет ЦА) и дописывались в англоязычный промт как
// есть. Для генератора русские слова — не текст, а случайный набор токенов:
// вместо уточнения он получал шум, и «исправленный» креатив выходил хуже
// исходного (в прогоне 82 у V4 стало 4 «нет» вместо 3). Поэтому берём
// английские двойники полей из брифа — style_en, focus_en, *_en.
// ============================================================================

const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const bad = {};
  (j.checklist || []).forEach(function (c) { if (c.answer === 'нет') bad[c.key] = true; });

  const fixes = [];

  if (bad.brief) {
    fixes.push('strictly follow the declared style (' + j.style_en +
      ') and the composition focus (' + j.composition_focus_en +
      '), keep the brand palette: deep navy blue #1B3A6B as the base colour, ' +
      'orange accent #FF7A45 used sparingly, light grey background #F5F7FA; ' +
      j.placement_text_zone_en);
  }
  if (bad.audience) {
    fixes.push('the person in the frame must look like the target audience: ' +
      j.segment_who_en + '; the scene must show this situation: ' + j.segment_insight_en);
  }
  if (bad.forbidden) {
    fixes.push('absolutely no text, no letters, no numbers, no words, no logo, no watermark, ' +
      'no brand marks, no flags, no children, no alcohol, no weapons');
  }
  if (bad.quality) {
    fixes.push('sharp focus, natural anatomy, correct hands with exactly five fingers, ' +
      'clean uncluttered composition, professional commercial photography');
  }

  const attempt = Number(j.attempt || 1) + 1;
  const joined = (j.prompt + '. ' + fixes.join('; ')).replace(/\s+/g, ' ').trim();

  // Страховка на случай, если кириллица всё-таки приползла из брифа: вырезаем
  // её из промта и честно помечаем это в реестре, а не отправляем молча.
  const stripped = joined.replace(/(?:[А-Яа-яЁё][А-Яа-яЁё\s,;:.()«»—–-]*)+/g, ' ');
  const prompt = stripped.replace(/\s+/g, ' ').replace(/\s+([;,.])/g, '$1').replace(/;\s*;/g, ';').trim();
  const prompt_language_fixed = prompt !== joined;

  out.push({
    json: Object.assign({}, j, {
      attempt: attempt,
      prompt: prompt,
      prompt_source: j.prompt_source + ' + правка',
      prompt_language_fixed: prompt_language_fixed,
      seed: j.seed,
      file_name: j.id + '-a' + attempt + '.webp',
      fix_reason: (j.checklist || []).filter(function (c) { return c.answer === 'нет'; })
        .map(function (c) { return c.label; }).join(' '),
      fix_comment: j.vision_improve || '',
      previous_image_url: j.image_url,
      previous_file_name: j.file_name,
      previous_checklist: j.checklist,
      previous_no_count: j.no_count,
      previous_comment: j.vision_comment,
      fixed_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss')
    })
  });
}

return out;

// ============================================================================
// ШАГ 4. ГЕНЕРАЦИЯ ИЗОБРАЖЕНИЙ
// ----------------------------------------------------------------------------
// Бесплатные публичные генераторы живут неровно, поэтому эшелонов три.
//
//   1) Быстрый эшелон — публичные спейсы Hugging Face на ZeroGPU
//      (FLUX.1-merged, Kolors, FLUX.1-dev). Отдают ссылку за секунды, но
//      квота у них на IP, а не на запрос: когда она выбрана, все три спейса
//      отвечают «event: error / data: null» за пару секунд. Поэтому спейсы
//      проверяются ОДНИМ пробным запросом на первом же варианте, а не
//      двадцатью четырьмя, как было бы при переборе по каждому варианту.
//   2) Основной эшелон — Stable Horde, краудсорсинг-сеть воркеров. Ключ не
//      нужен (анонимный '0000000000'), квоты нет, отдаёт base64. Но очередь
//      анонимного клиента тем длиннее, чем «дороже» задание: у задачи на
//      512x512 она стартует сразу, у 1024x1024 может стоять сотни позиций.
//      В часы нагрузки сервис вдобавок закрывает крупные запросы порогом
//      «заслуг»: «Due to heavy demand, for requests over 1024x1024 or over the
//      applicable first-order-equivalent sampler work budget the client needs to
//      already have the required kudos» (замер tools/horde-queue-probe.py:
//      задача 1024x1024 у SDXL 1.0 стояла 295-й, а та же сцена 512x512 —
//      нулевой). Порог считается по площади и числу шагов, поэтому список из
//      нескольких SDXL-моделей его тоже перешагивает: он оценивается дороже
//      одной модели (20.03 против 18.0) и был отклонён. Отсюда правило: у
//      основного эшелона ровно одна модель, а лёгкий запас — рабочий путь, а
//      не редкая страховка (в прогоне 86 тяжёлый размер так и не дошёл).
//   3) Лёгкий запас — если за HORDE_FAST_AFTER_MS ни одна задача основного
//      эшелона не сдвинулась с места, недостающие варианты досылаются в
//      уменьшенном размере с меньшим числом шагов. Первичные задачи при этом
//      продолжают опрашиваться: что придёт раньше — то и пойдёт в результат.
//      Фактический размер пишется в поле size_actual.
//
// Pollinations.ai (вариант, который пробовали первым) в работу не годится:
// на любой новый запрос отвечает 402 Payment Required, картинку отдаёт только
// из кэша — проверено tools/horde-size-test.py и отдельной пробой параметров.
//
// ВАЖНО про бинарные данные: Code-узел в этом n8n НЕ умеет скачивать бинарник
// по сети — helpers.httpRequest отдаёт побитую строку (проверено диагностикой
// tools/probe-binary-roundtrip.py: 28710 «байт» вместо 30320). Зато base64,
// полученный как обычный JSON, Code-узел превращает в настоящий файл без потерь
// (md5 совпадает). Поэтому:
//   • быстрый эшелон отдаёт ССЫЛКУ  -> её скачивает узел HTTP Request;
//   • Stable Horde отдаёт BASE64     -> его собирает узел «Картинка из base64».
// Дальше ветки сходятся на узле сохранения файла.
// ============================================================================

const H = this.helpers;
const items = $input.all();

function sleep(ms) {
  return new Promise(function (resolve) { setTimeout(resolve, ms); });
}

function msg(e) {
  return String((e && e.message) || e);
}

// --- эшелон 1: публичные спейсы Hugging Face --------------------------------
const HF_PROVIDERS = [
  {
    name: 'FLUX.1-merged (multimodalart)',
    host: 'https://multimodalart-flux-1-merged.hf.space',
    endpoint: '/infer',
    body: function (t) { return { data: [t.prompt, t.seed, false, t.width, t.height, 3.5, 4] }; }
  },
  {
    name: 'Kolors (Kwai)',
    host: 'https://kwai-kolors-kolors.hf.space',
    endpoint: '/infer',
    body: function (t) {
      return { data: [t.prompt, null, 0.5, negativeFor(t), t.seed, false, t.width, t.height, 5.0, 25] };
    }
  },
  {
    name: 'FLUX.1-dev (black-forest-labs)',
    host: 'https://black-forest-labs-flux-1-dev.hf.space',
    endpoint: '/infer',
    body: function (t) { return { data: [t.prompt, t.seed, false, t.width, t.height, 3.5, 4] }; }
  }
];

async function hfOnce(provider, t) {
  const call = await H.httpRequest({
    url: provider.host + '/gradio_api/call' + provider.endpoint,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: provider.body(t),
    json: true,
    timeout: 30000
  });

  const eventId = call && call.event_id;
  if (!eventId) throw new Error('спейс не вернул event_id');

  const stream = await H.httpRequest({
    url: provider.host + '/gradio_api/call' + provider.endpoint + '/' + eventId,
    method: 'GET',
    encoding: 'utf8',
    timeout: 180000
  });

  const text = String(stream || '');
  if (/event:\s*error/.test(text)) {
    throw new Error('спейс отклонил задание (квота ZeroGPU или ошибка модели)');
  }
  const m = text.match(/"url"\s*:\s*"([^"]+)"/);
  if (!m) throw new Error('в ответе спейса нет ссылки на картинку');
  return m[1];
}

// --- эшелон 2 и 3: Stable Horde ---------------------------------------------
const HORDE_API = 'https://stablehorde.net/api/v2';
const HORDE_KEY = '0000000000';   // анонимный ключ Stable Horde
const HORDE_MODEL = 'SDXL 1.0';

// Модели для лёгкого запаса — с родным разрешением 512 (SD 1.5-финетюны).
// SDXL 1.0 рассчитан на 1024: на 512x512 он уходит в плоскую стилизацию, и
// «запасная» картинка получается абстрактной — в прогоне 82 так вышли V1 и V3,
// чек-лист поставил им 4 и 3 «нет» именно за это.
//
// Base-модель stable_diffusion из списка убрана: в прогоне 86 она нарисовала
// «руки над блокнотом» вместо героини в кадре и куклу вместо женщины у стола,
// и чек-лист справедливо поставил этим вариантам «нет» за соответствие брифу.
// Замер на одном и том же промте (tools/horde-model-pick.py, 512x512, 30 шагов)
// показал, что финетюны держат сцену, а base-модель её теряет. AbsoluteReality
// стоит первым: у него кадр совпал с брифом лучше всех — героиня в тёмно-синем
// костюме с оранжевым акцентом, брендовая палитра и свободная левая половина.
// Порядок в списке — приоритет: Stable Horde берёт первую модель, воркер
// которой свободен.
const HORDE_MODELS_FAST = ['AbsoluteReality', 'Realistic Vision', 'Deliberate'];
const HORDE_POLL_MS = 15000;
const HORDE_MAX_WAIT_MS = 35 * 60 * 1000;   // общий потолок ожидания очереди
// Столько ждём «тяжёлый» размер, прежде чем досылать лёгкий. Замер на боевых
// конфигурациях (tools/horde-size-test.py): задача 1024x1024 у анонимного
// клиента стояла 189-й в общей очереди и за 15 минут не сдвинулась, а та же
// сцена в 512x512 на модели с родным разрешением 512 стартовала сразу
// (queue_position 0, 13 свободных воркеров) и была готова за 1,9 минуты.
const HORDE_FAST_AFTER_MS = 3 * 60 * 1000;
// Анонимному клиенту сервис разрешает около одного запроса в секунду и отвечает
// 429, если частить. Паузы держим и между отправками, и между опросами: иначе
// пачка проверок «съедает» лимит, отправка лёгкого размера падает, и узел
// честно ждёт тяжёлую очередь до самого потолка.
const HORDE_GAP_MS = 1500;
const HORDE_POLL_GAP_MS = 400;
// Окно на «повышение» размера. Цикл выходит, как только закрылась последняя
// дырка, поэтому лёгкая картинка успевала проскочить раньше тяжёлой и оставалась
// в результате навсегда — тяжёлая задача при этом ещё стояла в очереди и её
// никто не ждал. Теперь после сборки всех вариантов даём живым тяжёлым задачам
// ещё немного времени: что успело — заменит лёгкую картинку.
const HORDE_UPGRADE_GRACE_MS = 8 * 60 * 1000;

// Воркеры Stable Horde берут размеры, кратные 64. Пропорции площадок держим
// точно, а по площади не выходим за 1024x1024: у анонимного клиента запрос
// крупнее требует «заслуг» (KudosUpfront).
const HORDE_SIZES = {
  '1:1': [1024, 1024],
  '4:5': [768, 960],
  '3:4': [768, 1024],
  '4:3': [1024, 768],
  '16:9': [1024, 576]
};

// Лёгкий запас: те же пропорции, но маленькая площадь — такие задачи анонимной
// очереди стартуют почти сразу.
const HORDE_SIZES_FAST = {
  '1:1': [512, 512],
  '4:5': [512, 640],
  '3:4': [512, 640],
  '4:3': [512, 384],
  '16:9': [576, 320]
};

// Английский список запретов, собранный из restrictions.forbidden_elements
// брифа. Это не только запасной вариант: генератор понимает английские слова,
// поэтому русский negative из брифа ему бесполезен (см. negativeFor ниже).
const DEFAULT_NEGATIVE = 'text, letters, numbers, words, captions, watermark, ' +
  'logo, signature, brand logos, apple logo, laptop logo, headset logo, ' +
  'device brand marks, stickers on devices, flags, coats of arms, maps, ' +
  'political or religious symbols, Big Ben, red double-decker bus, cup of tea, ' +
  'royal guard, Tower Bridge, children, teenagers, school chalkboard, ' +
  'celebrities, real people, alcohol, tobacco, weapons, blood, gambling, drugs, ' +
  'medical masks, disasters, nudity, distorted face, extra fingers, fused ' +
  'fingers, deformed limbs, low quality, blurry, jpeg artifacts, collage, ' +
  'frame, gradient stock background';

// SDXL и другие диффузионные модели работают через английский CLIP: русские
// слова для них — не текст, а случайные токены, то есть запретов становится ноль.
// Агент писал negative по-русски (так же, как сформулированы запреты в брифе),
// и в генератор уходил неработающий набор. Поэтому здесь проверяем язык: если
// кириллица есть — берём английский список, а исходный текст сохраняем для
// реестра отдельным полем.
function negativeFor(t) {
  const n = String(t.negative || '');
  if (n.length > 3 && !/[А-Яа-яЁё]/.test(n)) return n;
  return DEFAULT_NEGATIVE;
}

async function horde(path, method, body) {
  const options = {
    url: HORDE_API + path,
    method: method,
    headers: {
      apikey: HORDE_KEY,
      'Client-Agent': 'n8n-visual-creatives:1.0:anonymous',
      'Content-Type': 'application/json'
    },
    json: true,
    timeout: 60000
  };
  if (body) options.body = body;
  return await H.httpRequest(options);
}

function hordeBody(t, size, steps, models) {
  return {
    prompt: t.prompt,
    params: {
      width: size[0],
      height: size[1],
      steps: steps,
      cfg_scale: 7,
      sampler_name: 'k_euler_a',
      n: 1,
      seed: String(t.seed === undefined || t.seed === null ? 0 : t.seed),
      negative_prompt: negativeFor(t)
    },
    nsfw: false,
    censor_nsfw: true,
    trusted_workers: false,
    slow_workers: true,
    models: models || [HORDE_MODEL],
    r2: false
  };
}

function sniffImage(buf) {
  if (buf[0] === 0x89 && buf[1] === 0x50) return { mime: 'image/png', ext: 'png' };
  if (buf[0] === 0xFF && buf[1] === 0xD8) return { mime: 'image/jpeg', ext: 'jpg' };
  if (buf[0] === 0x52 && buf[1] === 0x49) return { mime: 'image/webp', ext: 'webp' };
  return { mime: 'image/png', ext: 'png' };
}

// --- эшелон 1: быстрые спейсы -----------------------------------------------
const result = [];
const errors = [];

if (items.length) {
  // Квота у спейсов одна на IP, поэтому сначала один пробный запрос: если он
  // не прошёл — перебирать остальные варианты бессмысленно и долго.
  let hfProvider = null;
  for (const provider of HF_PROVIDERS) {
    try {
      result[0] = { url: await hfOnce(provider, items[0].json), provider: provider.name, attempt: 1 };
      hfProvider = provider;
      break;
    } catch (e) {
      errors.push(items[0].json.id + ' | проверка ' + provider.name + ': ' + msg(e));
      await sleep(1000);
    }
  }

  if (hfProvider) {
    for (let i = 1; i < items.length; i++) {
      try {
        result[i] = { url: await hfOnce(hfProvider, items[i].json), provider: hfProvider.name, attempt: 1 };
      } catch (e) {
        errors.push(items[i].json.id + ' | ' + hfProvider.name + ': ' + msg(e));
      }
    }
  }
}

// --- эшелоны 2 и 3: Stable Horde --------------------------------------------
const needHorde = [];
for (let i = 0; i < items.length; i++) {
  if (!result[i]) needHorde.push(i);
}

const hordeNote = [];

if (needHorde.length) {
  const jobs = [];        // {id, index, size, fast, taken}
  const pending = {};     // id -> job

  async function submitJob(idx, fast) {
    const t = items[idx].json;
    const table = fast ? HORDE_SIZES_FAST : HORDE_SIZES;
    const size = table[t.placement_ratio] || (fast ? HORDE_SIZES_FAST['1:1'] : HORDE_SIZES['1:1']);
    const models = fast ? HORDE_MODELS_FAST : [HORDE_MODEL];
    try {
      const sub = await horde('/generate/async', 'POST', hordeBody(t, size, fast ? 30 : 25, models));
      if (!sub || !sub.id) throw new Error('сервис не вернул id задания');
      const job = { id: sub.id, index: idx, size: size, fast: fast, models: models, taken: false };
      jobs.push(job);
      pending[sub.id] = job;
      return true;
    } catch (e) {
      errors.push(t.id + ' | Stable Horde (отправка ' + size[0] + 'x' + size[1] + '): ' + msg(e));
      return false;
    }
  }

  const startedAt = Date.now();
  const missing = function () {
    return needHorde.filter(function (i) { return !result[i]; });
  };

  for (const idx of needHorde) {
    await submitJob(idx, false);
    await sleep(HORDE_GAP_MS);
  }

  let fastSwitched = false;
  const faulted = {};
  const fastTries = {};

  // Варианты, которые уже закрыты лёгкой картинкой, но у которых тяжёлая задача
  // ещё жива: ради них и держим окно ожидания.
  const upgradeable = function () {
    const list = [];
    for (let i = 0; i < items.length; i++) {
      const r = result[i];
      if (!r || !r.fast) continue;
      const alive = jobs.some(function (j) {
        return j.index === i && !j.fast && pending[j.id];
      });
      if (alive) list.push(i);
    }
    return list;
  };

  let upgradeDeadline = null;

  while (Date.now() - startedAt < HORDE_MAX_WAIT_MS) {
    if (!missing().length) {
      const waiting = upgradeable();
      if (!waiting.length) break;
      if (upgradeDeadline === null) {
        upgradeDeadline = Date.now() + HORDE_UPGRADE_GRACE_MS;
        hordeNote.push('лёгкие картинки собраны, ждём тяжёлый размер ещё ' +
          Math.round(HORDE_UPGRADE_GRACE_MS / 60000) + ' мин: ' +
          waiting.map(function (i) { return items[i].json.id; }).join(', '));
      }
      if (Date.now() > upgradeDeadline) break;
    }
    await sleep(HORDE_POLL_MS);

    let moving = 0;
    for (const id of Object.keys(pending)) {
      const job = pending[id];
      const have = result[job.index];
      // Готовый результат — не повод бросить задачу: лёгкая картинка уже есть,
      // но тяжёлую мы всё ещё ждём, чтобы она её заменила. Раньше здесь стояла
      // проверка «result есть — удалить», и тяжёлая задача пропадала из pending
      // в тот же круг, как приходила лёгкая. Окно ожидания после этого не
      // находило живых тяжёлых задач и закрывалось мгновенно.
      if (have && (job.fast || !have.fast)) { delete pending[id]; continue; }
      try {
        const check = await horde('/generate/check/' + id, 'GET');
        if (!check) continue;
        if (check.done) {
          // забираем картинку
          const status = await horde('/generate/status/' + id, 'GET');
          const gen = (status && status.generations && status.generations[0]) ? status.generations[0] : null;
          if (gen && gen.img) {
            const buf = Buffer.from(gen.img, 'base64');
            if (buf.length) {
              // тяжёлый размер важнее лёгкого: если место ещё свободно — берём его
              if (!result[job.index] || (result[job.index].fast && !job.fast)) {
                const kind = sniffImage(buf);
                result[job.index] = {
                  base64: gen.img,
                  provider: 'Stable Horde (' + (gen.model || HORDE_MODEL) + ')',
                  ext: kind.ext,
                  mime: kind.mime,
                  bytes: buf.length,
                  seed: gen.seed,
                  fast: job.fast,
                  size: job.size
                };
                hordeNote.push(items[job.index].json.id + ': ' + String(gen.model || HORDE_MODEL) +
                  ' ' + job.size[0] + 'x' + job.size[1]);
              }
            } else {
              errors.push(items[job.index].json.id + ' | Stable Horde: картинка не декодировалась');
            }
          } else {
            errors.push(items[job.index].json.id + ' | Stable Horde: пустой ответ без картинки');
          }
          delete pending[id];
          continue;
        }
        if (check.faulted) {
          if (!faulted[job.index]) {
            errors.push(items[job.index].json.id + ' | Stable Horde (' + job.size[0] + 'x' + job.size[1] +
              '): задание отклонено');
            faulted[job.index] = true;
          }
          delete pending[id];
          continue;
        }
        const q = check.queue_position;
        if (check.processing || (typeof q === 'number' && q < 40)) moving++;
      } catch (e) {
        // одиночный сбой опроса не должен ронять весь цикл
      }
      await sleep(HORDE_POLL_GAP_MS);
    }

    // Лёгкий запас: тяжёлые задачи стоят в очереди — досылаем уменьшенные.
    // Отправка может не пройти (лимит запросов, сбой сети), поэтому пробуем
    // в каждом круге опроса, пока у варианта нет ни лёгкой задачи, ни картинки.
    if (Date.now() - startedAt > HORDE_FAST_AFTER_MS && missing().length) {
      if (!fastSwitched) {
        fastSwitched = true;
        hordeNote.push('включён лёгкий размер (в очереди оставалось ' +
          jobs.filter(function (j) { return !faulted[j.index]; }).length + ' задач)');
      }
      for (const idx of missing()) {
        const hasFast = jobs.some(function (j) {
          return j.index === idx && j.fast && pending[j.id];
        });
        if (hasFast) continue;
        // пять попыток на вариант: если сервис стабильно отказывает,
        // долбить его каждые 15 секунд до потолка бессмысленно
        fastTries[idx] = (fastTries[idx] || 0);
        if (fastTries[idx] >= 5) continue;
        fastTries[idx]++;
        await submitJob(idx, true);
        await sleep(HORDE_GAP_MS);
      }
    }
  }

  const still = missing();
  if (still.length) {
    errors.push('Stable Horde: за ' + Math.round(HORDE_MAX_WAIT_MS / 60000) +
      ' мин не дождались картинок для: ' + still.map(function (i) { return items[i].json.id; }).join(', '));
  }

  // Окно закрылось, а тяжёлые задачи так и не дошли: фиксируем это в реестре,
  // чтобы «size_downgraded: true» не выглядел случайностью.
  const notUpgraded = upgradeable();
  if (notUpgraded.length) {
    hordeNote.push('тяжёлый размер не догнал за окно ожидания: ' +
      notUpgraded.map(function (i) { return items[i].json.id; }).join(', ') + ' — оставлен лёгкий');
  }
}

// --- собираем результат ------------------------------------------------------
const out = [];

for (let i = 0; i < items.length; i++) {
  const t = Object.assign({}, items[i].json);
  const r = result[i];

  if (!r) {
    throw new Error('Ни один генератор не отдал изображение для варианта ' + t.id + '. ' +
      errors.join(' | '));
  }

  t.generator = r.provider;
  t.generator_attempt = r.attempt || 1;
  t.generator_errors = errors.slice();
  // Заметки по ходу ожидания (какой размер, что успело дойти) — раньше они
  // копились в массиве и никуда не попадали: в реестре не было видно, почему
  // у креатива понижен размер.
  t.generator_note = hordeNote.slice();
  // Что именно ушло в генератор как запрет и почему: если negative_used не
  // совпадает с negative из ответа агента, значит исходный был на кириллице и
  // модель его всё равно не поняла.
  t.negative_used = negativeFor(t);
  t.negative_source = (t.negative_used === String(t.negative || ''))
    ? 'ответ агента' : 'английский список из брифа (ответ агента был на русском)';
  t.generated_at = $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss');

  if (r.url) {
    // быстрый эшелон: картинку скачает следующий узел HTTP Request
    t.image_url = r.url;
    t.image_b64 = null;
    t.image_delivery = 'url';
    t.size_actual = t.width + 'x' + t.height;
  } else {
    // Stable Horde: base64 -> бинарник соберёт узел «Картинка из base64»
    t.image_url = null;
    t.image_b64 = r.base64;
    t.image_delivery = 'base64';
    t.image_mime = r.mime;
    t.file_name = String(t.file_name).replace(/\.[a-z0-9]+$/i, '') + '.' + r.ext;
    if (r.seed !== undefined && r.seed !== null) t.seed_actual = r.seed;
    t.size_actual = r.size[0] + 'x' + r.size[1];
    t.size_downgraded = !!r.fast;
    t.width = r.size[0];
    t.height = r.size[1];
  }

  out.push({ json: t });
}

return out;

// ============================================================================
// ШАГ 4б. КАРТИНКА ИЗ BASE64 (ветка запасного генератора)
// ----------------------------------------------------------------------------
// Нужен для Stable Horde: он отдаёт не ссылку, а картинку в base64 внутри JSON.
// Code-узел не умеет тянуть бинарник из сети, но base64 -> файл он собирает
// без потерь: проверено диагностикой tools/probe-binary-roundtrip.py —
// md5 записанного файла совпадает с исходным.
//
// Тип файла определяем по «магическим» байтам, а не по расширению: воркеры
// Stable Horde отдают то webp, то png, то jpg.
// ============================================================================

const H = this.helpers;
const items = $input.all();
const out = [];

function sniffImage(buf) {
  if (buf[0] === 0x89 && buf[1] === 0x50) return { mime: 'image/png', ext: 'png' };
  if (buf[0] === 0xFF && buf[1] === 0xD8) return { mime: 'image/jpeg', ext: 'jpg' };
  if (buf[0] === 0x52 && buf[1] === 0x49) return { mime: 'image/webp', ext: 'webp' };
  return { mime: 'image/png', ext: 'png' };
}

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;

  if (!j.image_b64) {
    throw new Error('Нет base64-изображения для варианта ' + j.id + ' — ветка вызвана ошибочно.');
  }

  const buf = Buffer.from(j.image_b64, 'base64');
  if (!buf.length) {
    throw new Error('Base64-изображение варианта ' + j.id + ' не декодировалось.');
  }

  const kind = sniffImage(buf);
  const fileName = String(j.file_name).replace(/\.[a-z0-9]+$/i, '') + '.' + kind.ext;
  const bin = await H.prepareBinaryData(buf, fileName, kind.mime);

  const next = Object.assign({}, j, {
    file_name: fileName,
    image_mime: kind.mime,
    image_bytes: buf.length,
    image_kb: Math.round(buf.length / 1024)
  });
  delete next.image_b64;   // дальше картинка живёт в binary, base64 в JSON не нужен

  out.push({ json: next, binary: { data: bin } });
}

return out;

// ============================================================================
// ШАГ 5. ЗАПРОС К VISION-МОДЕЛИ
// ----------------------------------------------------------------------------
// Готовит тело запроса к Ollama: промт проверки и картинку в base64.
//
// ВАЖНО про бинарные данные. В этом n8n бинарники хранятся в файловом режиме
// (N8N_DEFAULT_BINARY_DATA_MODE=filesystem): в поле binary.data.data лежит не
// base64-строка, а короткая ссылка вида "filesystem-v2". Поэтому байты надо
// доставать хелпером getBinaryDataBuffer — он возвращает настоящий Buffer
// внутри Code-узла, и уже его переводим в base64.
// (Проверено диагностикой tools/probe-binary.py: ссылка длиной 13 символов
//  против 40826 байт у getBinaryDataBuffer.)
// ============================================================================

const H = this.helpers;
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const bin = (items[i].binary && items[i].binary.data) ? items[i].binary.data : null;

  if (!bin) {
    throw new Error('Нет бинарных данных изображения для варианта ' + j.id + ' (' + j.file_name + ')');
  }

  let b64 = null;
  let bytes = 0;
  try {
    const buf = await H.getBinaryDataBuffer(i, 'data');
    if (Buffer.isBuffer(buf) && buf.length > 0) {
      b64 = buf.toString('base64');
      bytes = buf.length;
    }
  } catch (e) {
    throw new Error('Не удалось прочитать байты изображения ' + j.file_name + ': ' +
      String((e && e.message) || e));
  }

  if (!b64) {
    throw new Error('Пустые байты изображения ' + j.file_name);
  }

  const st = j.settings || {};

  const prompt = [
    'Ты — арт-директор онлайн-школы английского языка. Оцени готовый рекламный креатив по чек-листу заказчика.',
    '',
    j.vision_context,
    '',
    'ПРОВЕРЯЕМЫЙ ВАРИАНТ ' + j.id + ':',
    'Сегмент ЦА: ' + j.segment_id + ' — ' + j.segment_name + '. ' + j.segment_who + '. Инсайт: ' + j.segment_insight + '.',
    'Площадка: ' + j.placement_id + ' — ' + j.placement_name + ', ' + j.placement_size + ' (' + j.placement_ratio + '), зона под текст: ' + j.placement_text_zone + '.',
    'Заявленный стиль: ' + j.style + '. Фокус: ' + j.composition_focus + '. Акцент: ' + j.accent + '.',
    'Задание генератору (промт): ' + j.prompt,
    '',
    'ЧЕК-ЛИСТ — ответь «да» или «нет» по каждому пункту:',
    '1. brief — соответствие брифу, бренду и площадке: сюжет и настроение совпадают с описанием, пропорция и композиция подходят площадке, зона под будущий текст действительно свободна, цвета согласуются с палитрой бренда и заявленным стилем.',
    '2. audience — релевантность ЦА: изображённый человек и ситуация выглядят как описанный сегмент (возраст, контекст, уровень жизни), не вызывают отторжения у этой аудитории.',
    '3. forbidden — отсутствие запрещённых элементов: на картинке нет текста, букв и цифр, логотипов и водяных знаков, флагов и политической символики, стереотипов об Англии, детей, алкоголя, оружия, искажённых лиц и лишних пальцев.',
    '4. quality — техническое качество: композиция читается, изображение резкое, нет артефактов генерации, креатив пригоден для публикации в ленте.',
    '',
    'Ответь СТРОГО одним JSON-объектом, без markdown и без текста вокруг:',
    '{"brief":"да|нет","audience":"да|нет","forbidden":"да|нет","quality":"да|нет","comment":"1-2 предложения: что изображено и общее впечатление","improve":"одно предложение, что конкретно поправить, если есть «нет»; иначе — правки не нужны"}'
  ].join('\n');

  out.push({
    json: Object.assign({}, j, {
      ollama_model: st.vision_model || 'deepseek-v4.1-flash:cloud',
      vision_temperature: (st.vision_temperature === undefined ? 0.1 : st.vision_temperature),
      vision_prompt: prompt,
      image_b64: b64,
      image_bytes: bytes,
      image_kb: Math.round(bytes / 1024)
    })
  });
}

return out;

// ============================================================================
// ШАГ 6. ОЦЕНКА ПО ЧЕК-ЛИСТУ
// ----------------------------------------------------------------------------
// Разбирает ответ vision-модели и превращает его в четыре пункта чек-листа —
// ровно те, что стоят в шаблоне задания:
//   • соответствие брифу, бренду, площадке;
//   • релевантность ЦА;
//   • отсутствие запрещённых элементов;
//   • техническое качество.
//
// Метаданные варианта берём из узла Собрать запрос к Vision (правка): узел HTTP Request с ответом Ollama
// подменяет json целиком, поэтому «своих» полей в текущем элементе уже нет.
//
// Здесь же решается, нужна ли правка: по условию задания креатив уходит на
// повторную генерацию, только если ответов «нет» БОЛЬШЕ ДВУХ (то есть 3 или 4).
// ============================================================================

const SRC = $('Собрать запрос к Vision (правка)').all();
const items = $input.all();
const MAX_ATTEMPT = 2;

const CHECK = [
  { key: 'brief', label: 'соответствие брифу, бренду, площадке;' },
  { key: 'audience', label: 'релевантность ЦА' },
  { key: 'forbidden', label: 'отсутствие запрещённых элементов' },
  { key: 'quality', label: 'техническое качество.' }
];

function yesNo(value) {
  if (typeof value === 'boolean') return value ? 'да' : 'нет';
  const s = String(value === undefined || value === null ? '' : value).trim().toLowerCase();
  if (!s) return 'нет';
  if (/^(да|yes|true|1|ok|ок)/.test(s)) return 'да';
  return 'нет';
}

function parseModelJson(text) {
  const t = String(text || '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try {
    return JSON.parse(t.slice(a, b + 1));
  } catch (e) {
    return null;
  }
}

const out = [];

for (let i = 0; i < items.length; i++) {
  const meta = (SRC[i] && SRC[i].json) ? SRC[i].json : {};
  const st = meta.settings || {};
  const threshold = (st.fix_threshold === undefined) ? 2 : Number(st.fix_threshold);
  const attempt = Number(meta.attempt || 1);

  const answer = parseModelJson(items[i].json.response);
  const visionError = items[i].json.error || null;

  const checklist = CHECK.map(function (c) {
    return {
      key: c.key,
      label: c.label,
      answer: answer ? yesNo(answer[c.key]) : 'н/д'
    };
  });

  const noCount = checklist.filter(function (c) { return c.answer === 'нет'; }).length;
  const naCount = checklist.filter(function (c) { return c.answer === 'н/д'; }).length;

  // Правка нужна, только если чек-лист реально заполнен, «нет» больше порога
  // и попытки ещё остались.
  const needsFix = !!answer && noCount > threshold && attempt < MAX_ATTEMPT;

  out.push({
    json: Object.assign({}, meta, {
      attempt: attempt,
      checklist: checklist,
      no_count: noCount,
      na_count: naCount,
      fix_threshold: threshold,
      needs_fix: needsFix,
      max_attempt: MAX_ATTEMPT,
      vision_ok: !!answer,
      vision_error: answer ? null : String(visionError || 'модель не вернула разбираемый JSON').slice(0, 200),
      vision_comment: answer ? String(answer.comment || '').trim() : '',
      vision_improve: answer ? String(answer.improve || '').trim() : '',
      vision_raw: answer ? null : String(items[i].json.response || '').slice(0, 400),
      vision_error_dump: answer ? null : JSON.stringify(items[i].json).slice(0, 1500),
      evaluated_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss')
    })
  });
}

return out;

// ============================================================================
// ШАГ 8. РЕГИСТР КРЕАТИВОВ И ТАБЛИЦА РЕЗУЛЬТАТОВ
// ----------------------------------------------------------------------------
// 1. Сводит оценки первого прохода и повторного (если он был), по каждому
//    варианту оставляет ту попытку, которая победила.
// 2. Просит vision-модель сравнить альтернативу с базовым вариантом и получить
//    текст «чем отличается результат».
// 3. Собирает строки таблицы под шаблон задания, CSV, Markdown и полный JSON.
//
// Узел стоит после ветвления IF, поэтому в него приходят данные двумя путями.
// Содержимое он каждый раз собирает целиком из узлов-источников, а не из
// входящих элементов, — так результат одинаков независимо от порядка обхода.
// ============================================================================

const H = this.helpers;

function safeAll(nodeName) {
  try {
    const n = $(nodeName);
    return n && n.isExecuted ? n.all() : [];
  } catch (e) {
    return [];
  }
}

function parseModelJson(text) {
  const t = String(text || '');
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
}

const pack = $('Разобрать бриф').first().json;
const settings = pack.settings || {};
const variants = pack.tasks.map(function (t) { return t.id; });

// --- 1. Сводим оценки -------------------------------------------------------
const evaluated = [];
safeAll('Оценка по чек-листу').forEach(function (i) { evaluated.push(i.json); });
safeAll('Оценка после правки').forEach(function (i) { evaluated.push(i.json); });

// Попытку выбираем по числу «нет», а не по её номеру. Раньше побеждала самая
// поздняя, и в прогоне 87 это вышло боком: у V1 первая попытка дала 3 «нет», а
// «исправленная» — 4, но в таблицу попала именно она. При равенстве оставляем
// первую попытку: она сохраняет исходный кадр, а он важен — по заданию
// альтернатива V4 отличается от V1 ровно одним параметром.
// Попытку без оценки сравнивать нельзя: у неё в чек-листе стоят «н/д», и по
// числу «нет» она выглядела бы лучше всех, хотя модель просто не ответила.
function score(e) {
  return e.vision_ok === false ? 99 : Number(e.no_count || 0);
}

const best = {};
evaluated.forEach(function (e) {
  const cur = best[e.id];
  if (!cur) { best[e.id] = e; return; }
  const a = score(e);
  const b = score(cur);
  if (a < b || (a === b && Number(e.attempt) < Number(cur.attempt))) best[e.id] = e;
});

// --- карта base64: нужна для финального сравнения двух картинок -------------
const b64map = {};
safeAll('Собрать запрос к Vision').forEach(function (i) {
  b64map[i.json.id + '|' + i.json.attempt] = i.json.image_b64;
});
safeAll('Собрать запрос к Vision (правка)').forEach(function (i) {
  b64map[i.json.id + '|' + i.json.attempt] = i.json.image_b64;
});

// --- 2. Сравнение альтернативы с базовым вариантом --------------------------
const altTask = pack.tasks.filter(function (t) { return t.base_variant; })[0];
let differenceText = null;
let differenceSource = 'модель не ответила';

async function askDifference(base, alt) {
  const prompt = [
    'Перед тобой два рекламных креатива для одного продукта, одного сегмента ЦА и одной площадки.',
    'У них одинаковые сюжет, композиция, кадр и акцент — различается только стиль.',
    'Первый креатив: стиль «' + base.style + '». Второй креатив: стиль «' + alt.style + '».',
    'Опиши по-русски в 2–3 предложениях, чем отличается результат: что изменилось в цвете, свете,',
    'настроении, на что раньше обращает внимание зритель, как меняется восприятие бренда.',
    'Ответь строго одним JSON-объектом: {"difference":"текст"}'
  ].join('\n');

  const r = await H.httpRequest({
    method: 'POST',
    url: (settings.ollama_url || 'http://10.0.2.2:11434') + '/api/generate',
    body: {
      model: settings.vision_model || 'deepseek-v4.1-flash:cloud',
      prompt: prompt,
      images: [base.b64, alt.b64],
      stream: false,
      format: 'json',
      options: { temperature: 0.2 }
    },
    json: true,
    timeout: 300000
  });
  const a = parseModelJson(r.response);
  return a && a.difference ? String(a.difference).trim() : null;
}

if (altTask) {
  const baseId = altTask.base_variant;
  const baseEval = best[baseId];
  const altEval = best[altTask.id];
  const baseB64 = baseEval ? b64map[baseId + '|' + baseEval.attempt] : null;
  const altB64 = altEval ? b64map[altTask.id + '|' + altEval.attempt] : null;

  if (baseB64 && altB64) {
    try {
      const d = await askDifference(
        { b64: baseB64, style: baseEval.style },
        { b64: altB64, style: altEval.style }
      );
      if (d) { differenceText = d; differenceSource = 'vision-модель'; }
    } catch (e) {
      differenceSource = 'ошибка вызова модели: ' + String((e && e.message) || e).slice(0, 120);
    }
  }

  if (!differenceText) {
    differenceText = 'Стиль переведён из минимализма в яркий: тот же сюжет и композиция, но вместо ' +
      'светло-серого фона и мягкого света — насыщенная оранжево-синяя цветовая подложка и ' +
      'контрастный студийный свет. Изображение стало заметнее в ленте и читается как более ' +
      'энергичное, но ушло от сдержанной «премиальной» подачи бренда.';
    differenceSource = 'шаблон (модель недоступна)';
  }
} else {
  differenceText = '';
}

// --- 3. Строки таблицы, CSV, Markdown --------------------------------------
function yn(c, key) {
  const f = (c || []).filter(function (x) { return x.key === key; })[0];
  return f ? f.answer : 'н/д';
}

const rows = [];
variants.forEach(function (id) {
  const v = best[id];
  if (!v) return;
  const isAlt = !!v.base_variant;
  const altV = isAlt ? null : best[altTask ? altTask.id : ''];

  // Была ли правка и осталась ли она в результате. Это разные вещи: правка
  // могла отработать и проиграть первой попытке — тогда об этом надо сказать
  // прямо, иначе «>2 нет, а правки нет» выглядит как нарушение условия задания.
  const own = evaluated.filter(function (e) { return e.id === id; });
  const triedCount = own.length;
  const fixTried = own.some(function (e) { return Number(e.attempt) > 1; });
  const fixKept = Number(v.attempt) > 1;

  let comment = v.vision_comment || '';
  if (v.vision_ok === false) {
    comment = 'ОЦЕНКА НЕ ПОЛУЧЕНА — ' + String(v.vision_error || 'vision-модель не ответила') +
      '. Чек-лист не заполнен, повторная генерация не запускалась.';
  } else if (fixTried && !fixKept) {
    const worse = own.filter(function (e) { return Number(e.attempt) > 1; })[0];
    comment = (comment ? comment + ' ' : '') + 'Правка выполнена, но результат оказался хуже (' +
      Number(worse && worse.no_count) + ' «нет» против ' + Number(v.no_count) +
      ') — оставлен исходный вариант.';
  }

  rows.push({
    id: id,
    placement: v.placement_name + ', ' + v.placement_size,
    audience: v.segment_id + ' — ' + v.segment_name + '. ' + v.segment_who,
    params: [
      'промт (' + v.prompt_source + '): ' + v.prompt,
      'стиль: ' + v.style,
      'фокус: ' + v.composition_focus,
      'акцент: ' + v.accent,
      'размер: ' + (v.size_actual || (v.width + '×' + v.height)) +
        (v.size_downgraded ? ' (лёгкий запас: тяжёлый размер не дождался воркера)' : ''),
      'seed: ' + v.seed,
      'генератор: ' + (v.generator || 'н/д'),
      // Запреты видны в отчёте, потому что их источник неочевиден: агент пишет
      // negative по-русски, а генератор понимает только английский.
      'запреты (' + (v.negative_source || 'н/д') + '): ' + (v.negative_used || ''),
      v.prompt_language_fixed ? 'правка: кириллица вырезана из промта' : ''
    ].filter(Boolean).join('\n'),
    image_file: v.file_name,
    image_url: v.image_url,
    alternative_file: (v.id === (altTask ? altTask.base_variant : '')) && altV ? altV.file_name : '',
    alternative_url: (v.id === (altTask ? altTask.base_variant : '')) && altV ? altV.image_url : '',
    changed_parameter: isAlt ? (v.changed_parameter || '') : '',
    difference: isAlt ? differenceText : ((v.id === (altTask ? altTask.base_variant : '')) ? differenceText : ''),
    checklist: (v.checklist || []).map(function (c) { return { label: c.label, answer: c.answer }; }),
    no_count: v.no_count,
    na_count: v.na_count,
    // Оценки нет — это не «прошло»: пустые «н/д» в отчёте читаются как успех,
    // поэтому причину пишем прямо в комментарий, туда же, где ждёт арт-директора.
    vision_ok: v.vision_ok !== false,
    // Сколько попыток вообще было и какая из них осталась в результате: это
    // разные числа, когда правка проиграла первой попытке.
    attempts: triedCount,
    attempt_kept: Number(v.attempt),
    fixed: fixKept,
    fix_attempted: fixTried,
    comment: comment,
    improve: v.vision_improve
  });
});

// --- CSV (точка с запятой — Excel с русской локалью открывает корректно) ----
function csvCell(s) {
  return '"' + String(s === undefined || s === null ? '' : s).replace(/"/g, '""').replace(/\r?\n/g, ' ') + '"';
}

const csvHeader = ['Вариант', 'Площадка', 'ЦА', 'Параметры генерации', 'Файл', 'Ссылка',
  'Ссылка на альтернативу', 'Какой параметр изменён', 'Чем отличается результат',
  'соответствие брифу, бренду, площадке;', 'релевантность ЦА',
  'отсутствие запрещённых элементов', 'техническое качество.', 'Чек-лист заполнен',
  'Сколько «нет»', 'Попыток', 'Правка выполнена', 'Комментарий арт-директора'];

const csvLines = [csvHeader.map(csvCell).join(';')];
rows.forEach(function (r) {
  csvLines.push([
    r.id, r.placement, r.audience, r.params, r.image_file, r.image_url,
    r.alternative_file || '', r.changed_parameter, r.difference,
    yn(r.checklist, 'brief'), yn(r.checklist, 'audience'),
    yn(r.checklist, 'forbidden'), yn(r.checklist, 'quality'),
    r.vision_ok ? 'да' : 'нет',
    r.no_count, r.attempts, r.fix_attempted ? 'да' : 'нет', r.comment
  ].map(csvCell).join(';'));
});
const csv = csvLines.join('\r\n');

// --- Markdown ---------------------------------------------------------------
const md = [];
md.push('# Визуальные креативы: ' + pack.brief_summary.product + ' (' + pack.brief_summary.campaign + ')');
md.push('');
md.push('Сгенерировано агентом визуальных креативов. Вариантов: ' + rows.length +
  ', из них с правкой: ' + rows.filter(function (r) { return r.fixed; }).length + '.');
md.push('');
rows.forEach(function (r) {
  md.push('## ' + r.id + ' — ' + r.placement);
  md.push('');
  md.push('**ЦА:** ' + r.audience);
  md.push('');
  md.push('**Параметры:** ');
  md.push('```');
  md.push(r.params);
  md.push('```');
  md.push('**Файл:** `' + r.image_file + '`');
  md.push('');
  md.push('| Пункт чек-листа | Оценка |');
  md.push('|---|---|');
  r.checklist.forEach(function (c) { md.push('| ' + c.label + ' | ' + c.answer + ' |'); });
  md.push('');
  if (!r.vision_ok) {
    md.push('> **Чек-лист не заполнен:** ' + r.comment);
    md.push('');
  }
  if (r.fix_attempted && !r.fixed) {
    md.push('> **Правка не помогла.** ' + r.comment);
    md.push('');
  }
  if (r.alternative_file) {
    md.push('**Альтернатива:** `' + r.alternative_file + '` — ' + r.changed_parameter);
    md.push('');
    md.push('**Чем отличается результат:** ' + r.difference);
    md.push('');
  }
  md.push('**Комментарий арт-директора:** ' + (r.comment || '—'));
  md.push('');
});

const registry = {
  generated_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm:ss'),
  campaign: pack.brief_summary.campaign,
  product: pack.brief_summary.product,
  brand: pack.brief_summary.brand,
  fix_threshold: pack.fix_threshold,
  variants_total: rows.length,
  variants_fixed: rows.filter(function (r) { return r.fixed; }).length,
  difference_source: differenceSource,
  difference_text: differenceText,
  rows: rows,
  evaluations: evaluated
};

const summary = {
  status: 'ok',
  generated_at: registry.generated_at,
  variants: rows.length,
  fixed: registry.variants_fixed,
  files: rows.map(function (r) { return r.image_file; }),
  difference_source: differenceSource,
  checks_failed: rows.filter(function (r) { return r.no_count > 0; })
    .map(function (r) { return r.id + ': ' + r.no_count + ' «нет»'; }),
  // Варианты, по которым vision-модель не ответила: чек-лист у них не заполнен,
  // и это надо видеть в сводке, а не догадываться по «н/д» в таблице.
  evaluation_missing: rows.filter(function (r) { return !r.vision_ok; })
    .map(function (r) { return r.id; })
};

// Файлы сохраняются узлом readWriteFile, ему нужны бинарные данные,
// поэтому готовим их здесь (как в практике 3.1).
const files = [
  { name: 'registry.json', text: JSON.stringify(registry, null, 2), mime: 'application/json' },
  { name: 'registry.csv', text: csv, mime: 'text/csv' },
  { name: 'registry.md', text: md.join('\n'), mime: 'text/markdown' }
];

const out = [];
for (const f of files) {
  const bin = await H.prepareBinaryData(Buffer.from(f.text, 'utf8'), f.name, f.mime);
  out.push({ json: { file_name: f.name, summary: summary }, binary: { data: bin } });
}
return out;

// ============================================================================
// ФИНАЛЬНЫЙ УЗЕЛ
// ----------------------------------------------------------------------------
// Отдаёт короткую сводку прогона: её видно в интерфейсе n8n и получает тот,
// кто дёрнул агент по ссылке (webhook отвечает результатом последнего узла).
// Полные данные лежат в registry.json / registry.csv / registry.md на диске.
// ============================================================================

const s = $('Регистр креативов').first().json.summary;

const text = [
  'Готово. Креативов: ' + s.variants + ', из них с правкой: ' + s.fixed + '.',
  'Файлы: ' + s.files.join(', ') + '.',
  s.checks_failed.length
    ? 'Замечания чек-листа: ' + s.checks_failed.join('; ') + '.'
    : 'Чек-лист пройден без замечаний.'
].join(' ');

return [{
  json: {
    status: s.status,
    generated_at: s.generated_at,
    variants: s.variants,
    fixed: s.fixed,
    files: s.files,
    checks_failed: s.checks_failed,
    difference_source: s.difference_source,
    text: text
  }
}];
